SELECT 100.0 * SUM(CASE WHEN p.height < 180 AND pa.overall_rating > 70 THEN 1 ELSE 0 END) / SUM(CASE WHEN p.height < 180 THEN 1 ELSE 0 END) AS percentage
FROM Player p
JOIN (
  SELECT player_api_id, overall_rating
  FROM Player_Attributes pa1
  WHERE pa1.date = (
    SELECT MAX(pa2.date) FROM Player_Attributes pa2 WHERE pa2.player_api_id = pa1.player_api_id
  )
) pa ON pa.player_api_id = p.player_api_id;
